parameters.jsCode:
// Rozbijamy każdą wiadomość (item) na osobne itemy, po jednym na załącznik.
// Referencję do gotowych danych binarnych kopiujemy bezpośrednio
// (item.binary[klucz]) - dane przygotował już Email Trigger, więc nie ma
// czego budować przez this.helpers.prepareBinaryData(). Ten helper jest
// potrzebny tylko przy tworzeniu binarki od zera z surowego Buffera.
const wynik = [];

for (const item of $input.all()) {
  // Wiadomość bez sekcji binarnej (brak załączników) - pomijamy bez błędu,
  // to normalna ścieżka, nie wyjątek.
  if (!item.binary) {
    continue;
  }

  // "from" to obiekt mailparsera, nie string - adres siedzi w value[0].address.
  // Zabezpieczenie na wypadek pustej/brakującej tablicy: taki mail jest
  // patologiczny, ale to nie powód, żeby gubić fakturę razem z załącznikiem.
  // Zamiast pomijać całą wiadomość, zostawiam nadawcę jako null - dalszy
  // filtr porównujący nadawcę z wystawcą faktury dostanie jawny sygnał
  // "nie da się zweryfikować" i będzie mógł skierować item do ręcznej
  // weryfikacji zamiast po cichu zniknąć razem z dokumentem.
  const adresNadawcy = item.json.from?.value?.[0]?.address ?? null;

  // Kontekst wiadomości zapisany raz na item wejściowy, bo po rozbiciu
  // na osobne itemy załącznikowe traci się powiązanie z oryginalnym mailem.
  // idWiadomosci trzyma messageId, nie attributes.uid - uid jest unikalny
  // tylko w obrębie jednego folderu IMAP i unieważnia się przy operacjach
  // na skrzynce, więc nie nadaje się do identyfikacji wiadomości w dalszych
  // krokach przepływu.
  const kontekstWiadomosci = {
    nadawca: adresNadawcy,
    temat: item.json.subject,
    data: item.json.date,
    idWiadomosci: item.json.messageId,
  };

  // Klucze załączników (attachment_0, attachment_1, ...) są dynamiczne
  // i różne dla każdej wiadomości, więc iterujemy po Object.keys zamiast
  // zakładać konkretną nazwę albo maksymalną liczbę.
  for (const klucz of Object.keys(item.binary)) {
    const zalacznik = item.binary[klucz];

    wynik.push({
      json: {
        ...kontekstWiadomosci,
        nazwaPliku: zalacznik.fileName,
        typMime: zalacznik.mimeType,
      },
      // Stała nazwa "zalacznik" niezależnie od oryginalnego klucza -
      // kolejne węzły zawsze odwołują się do tego samego pola binarnego,
      // bez sprawdzania, którym z kolei załącznikiem w mailu on był.
      binary: {
        zalacznik: zalacznik,
      },
    });
  }
}

return wynik;

